"""Runnable Orion miner process on Bittensor."""

from __future__ import annotations

import re
from dataclasses import dataclass, replace
from typing import Callable, Mapping, Protocol

import bittensor as bt

from orion.chain.bittensor import (
    LiveBittensorChain,
)


_HASH_RE = re.compile(r"^[0-9a-f]{64}$")


def _integer(
    value: object,
    *,
    name: str,
    minimum: int,
    maximum: int,
) -> int:
    if type(value) is not int:
        raise TypeError(f"{name} must be an integer")
    if not minimum <= value <= maximum:
        raise ValueError(f"{name} is outside its allowed range")
    return value


def _option_integer(
    options: Mapping[str, str],
    name: str,
    *,
    minimum: int,
    maximum: int,
    default: str | None = None,
) -> int:
    raw = options.get(name, default)
    if raw is None or not isinstance(raw, str) or not raw.isascii():
        raise ValueError(f"{name} is required")
    try:
        value = int(raw, 10)
    except ValueError as error:
        raise ValueError(f"{name} must be a base-10 integer") from error
    return _integer(value, name=name, minimum=minimum, maximum=maximum)


def _required(options: Mapping[str, str], name: str) -> str:
    value = options.get(name)
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(f"{name} is required")
    return value


@dataclass(frozen=True, slots=True)
class MinerNeuronConfig:
    netuid: int
    network: str
    hotkey_ss58: str | None = None

    def __post_init__(self) -> None:
        _integer(self.netuid, name="netuid", minimum=0, maximum=2**16 - 1)
        if not isinstance(self.network, str) or not self.network:
            raise ValueError("network cannot be empty")
        if self.hotkey_ss58 is not None and (
            not isinstance(self.hotkey_ss58, str) or not self.hotkey_ss58
        ):
            raise ValueError("hotkey_ss58 must be a non-empty string")

    @classmethod
    def from_options(cls, options: Mapping[str, str]) -> "MinerNeuronConfig":
        return cls(
            network=_required(options, "network"),
            netuid=_option_integer(
                options,
                "netuid",
                minimum=0,
                maximum=2**16 - 1,
            ),
            hotkey_ss58=options.get("miner_hotkey_ss58"),
        )


class MinerApplication(Protocol):
    def start(self) -> object: ...

    def on_block(self, block: int, block_hash: str): ...

    def close(self) -> object: ...


class WalletIdentityError(ValueError):
    """The configured hotkey and the local signing wallet are not identical."""


def _load_wallet(
    options: Mapping[str, str],
    *,
    expected_hotkey: str | None,
    wallet_factory: Callable[..., object],
) -> object:
    try:
        arguments: dict[str, str] = {
            "name": _required(options, "wallet_name"),
            "hotkey": _required(options, "hotkey_name"),
        }
        wallet_path = options.get("wallet_path")
        if wallet_path is not None:
            if (
                not isinstance(wallet_path, str)
                or not wallet_path
                or wallet_path != wallet_path.strip()
            ):
                raise ValueError("wallet path is invalid")
            arguments["path"] = wallet_path
        wallet = wallet_factory(**arguments)
        observed_hotkey = wallet.hotkey.ss58_address
    except Exception as error:
        raise WalletIdentityError("wallet hotkey is unavailable") from error
    if expected_hotkey is not None and observed_hotkey != expected_hotkey:
        raise WalletIdentityError("wallet hotkey differs from configured miner identity")
    return wallet


class MinerNeuron:
    def __init__(
        self,
        *,
        config: MinerNeuronConfig,
        application: MinerApplication,
    ) -> None:
        if not isinstance(config, MinerNeuronConfig):
            raise TypeError("config must be a MinerNeuronConfig")
        if not callable(getattr(application, "on_block", None)):
            raise TypeError("application has no on_block operation")
        self.config = config
        self.application = application
        self._last_block: int | None = None
        self._last_hash: str | None = None
        self._last_result: object | None = None

    def on_block(self, block: int, block_hash: str):
        _integer(block, name="block", minimum=0, maximum=2**64 - 1)
        if not isinstance(block_hash, str) or _HASH_RE.fullmatch(block_hash) is None:
            raise ValueError("block hash must be canonical lowercase hex")
        if self._last_block is not None:
            if block < self._last_block:
                raise ValueError("block stream regressed")
            if block == self._last_block:
                if block_hash != self._last_hash:
                    raise ValueError("same block arrived with another hash (reorg)")
                return self._last_result
        result = self.application.on_block(block, block_hash)
        self._last_block = block
        self._last_hash = block_hash
        self._last_result = result
        return result

    def run(self, blocks) -> None:
        start = getattr(self.application, "start", None)
        close = getattr(self.application, "close", None)
        try:
            if callable(start):
                start()
            for header in blocks:
                block_hash = str(header.hash).removeprefix("0x").lower()
                self.on_block(int(header.number), block_hash)
        finally:
            if callable(close):
                close()


def build_live_neuron(
    options: Mapping[str, str],
) -> tuple[MinerNeuron, LiveBittensorChain]:
    """Build the process only when explicitly called by the CLI."""

    values = dict(options)
    config = MinerNeuronConfig.from_options(values)
    wallet = _load_wallet(
        values,
        expected_hotkey=config.hotkey_ss58,
        wallet_factory=bt.Wallet,
    )
    if config.hotkey_ss58 is None:
        config = replace(config, hotkey_ss58=wallet.hotkey.ss58_address)
    values["miner_hotkey_ss58"] = config.hotkey_ss58
    chain = LiveBittensorChain.from_network(config.network)
    try:
        from services.miner_production import build_discovering_miner_application

        application = build_discovering_miner_application(
            options=values,
            wallet=wallet,
            chain=chain,
        )
    except Exception:
        chain.close()
        raise
    return (
        MinerNeuron(
            config=config,
            application=application,
        ),
        chain,
    )


def main(*, options: Mapping[str, str]) -> int:
    neuron, chain = build_live_neuron(options)
    try:
        neuron.run(chain.blocks())
    finally:
        chain.close()
    return 0


if __name__ == "__main__":
    import sys

    from orion.cli import main as cli_main

    raise SystemExit(cli_main(("miner", "run", *sys.argv[1:])))


__all__ = [
    "MinerNeuron",
    "MinerNeuronConfig",
    "WalletIdentityError",
    "build_live_neuron",
]

