def _integer(
    value: object,
    *,
    name: str,
    minimum: int,
    maximum: int,
) -> int:
    if type(value) is not int:
        raise TypeError(f"{name} must be an integer")
    if not minimum <= value <= maximum:
        raise ValueError(f"{name} is outside its allowed range")
    return value


def _required(options: Mapping[str, str], name: str) -> str:
    value = options.get(name)
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(f"{name} is required")
    return value


def _option_integer(
    options: Mapping[str, str],
    name: str,
    *,
    minimum: int,
    maximum: int,
    default: str | None = None,
) -> int:
    raw = options.get(name, default)
    if raw is None or not isinstance(raw, str) or not raw.isascii():
        raise ValueError(f"{name} is required")
    try:
        value = int(raw, 10)
    except ValueError as error:
        raise ValueError(f"{name} must be a base-10 integer") from error
    return _integer(value, name=name, minimum=minimum, maximum=maximum)


def _set_weights_arm(options: Mapping[str, str]) -> bool:
    """Return the exact production SetWeights arm, defaulting to disarmed."""

    raw = options.get("set_weights_armed")
    if raw is None:
        return False
    if raw == "true":
        return True
    if raw == "false":
        return False
    raise ValueError("set_weights_armed must be exactly 'true' or 'false'")


def _load_campaign(options: Mapping[str, str]) -> CampaignManifest:
    raw = Path(_required(options, "campaign_path")).read_bytes()
    campaign = CampaignManifest.model_validate_json(raw)
    if campaign.canonical_bytes() != raw:
        raise ValueError("configured campaign is not canonical")
    trusted_publisher = _required(
        options,
        "campaign_publisher_hotkey",
    )
    if not verify_protocol_object(
        campaign,
        expected_signer_ss58=trusted_publisher,
        expected_crypto_type=bt.CRYPTO_SR25519,
    ):
        raise ValueError("configured campaign signature is invalid")
    return campaign


@dataclass(frozen=True, slots=True)
class EpochSchedule:
    epoch_open_block: int
    epoch_length_blocks: int

    def __post_init__(self) -> None:
        _integer(
            self.epoch_open_block,
            name="epoch_open_block",
            minimum=0,
            maximum=2**64 - 1,
        )
        _integer(
            self.epoch_length_blocks,
            name="epoch_length_blocks",
            minimum=1,
            maximum=2**64 - 1,
        )

    def epoch_at(self, block: int) -> int | None:
        _integer(block, name="block", minimum=0, maximum=2**64 - 1)
        if block < self.epoch_open_block:
            return None
        return (block - self.epoch_open_block) // self.epoch_length_blocks

    def settlement_block(self, epoch: int) -> int:
        _integer(epoch, name="epoch", minimum=0, maximum=2**64 - 1)
        return (
            self.epoch_open_block
            + (epoch + 1) * self.epoch_length_blocks
            - 1
        )

    def is_settlement_block(self, block: int) -> bool:
        epoch = self.epoch_at(block)
        return epoch is not None and block == self.settlement_block(epoch)

    def latest_closed_epoch(self, block: int) -> int | None:
        """Latest epoch whose inclusive final block is at or before ``block``."""

        _integer(block, name="block", minimum=0, maximum=2**64 - 1)
        first_close = self.settlement_block(0)
        if block < first_close:
            return None
        return (block - first_close) // self.epoch_length_blocks


class EpochOutcomeSource(Protocol):
