def _load_wallet(
    options: Mapping[str, str],
    *,
    expected_hotkey: str | None,
    wallet_factory: Callable[..., object],
) -> object:
    try:
        arguments: dict[str, str] = {
            "name": _required(options, "wallet_name"),
            "hotkey": _required(options, "hotkey_name"),
        }
        wallet_path = options.get("wallet_path")
        if wallet_path is not None:
            if (
