def _operator_hotkeys(campaign: CampaignManifest) -> tuple[str, ...]:
    return tuple(
        sorted(
            {
                campaign.operators.campaign_publisher_hotkey,
                campaign.operators.orchestrator_hotkey,
                campaign.operators.collector_hotkey,
                campaign.operators.materializer_hotkey,
            }
        )
    )


def _report_payload(
    *,
    campaign: CampaignManifest,
    epoch: int,
    observed_block: int,
    observed_block_hash: str,
    uid_map_block: int,
    uid_map_block_hash: str,
    active_hotkeys: tuple[str, ...],
    raw_rewards: Mapping[str, int],
    submission: WeightSubmissionResult,
    validation_outcomes: tuple[ValidationOutcomeDescriptor, ...] = (),
) -> bytes:
    payload = {
        "active_hotkeys": list(active_hotkeys),
        "campaign_id": campaign.campaign_id,
        "discovery_block": uid_map_block,
        "discovery_block_hash": uid_map_block_hash,
        "epoch": epoch,
        "observed_block": observed_block,
        "observed_block_hash": observed_block_hash,
        "raw_rewards_by_hotkey": dict(raw_rewards),
        "submission": {
            "block": submission.block,
            "block_hash": submission.block_hash,
            "dropped_hotkeys": list(submission.dropped_hotkeys),
            "reason": submission.reason,
            "submitted": submission.submitted,
        },
        "validation_outcomes": [
            value.model_dump(mode="json") for value in validation_outcomes
        ],
        "version": 2,
    }
    return json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    ).encode("ascii")


def _recovered_rewards(raw: bytes, *, campaign_id: str) -> Mapping[str, int]:
    """Recover only the authenticated hotkey reward vector needed to refresh."""

    try:
        payload = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("recovered validator report payload is not JSON") from error
    if (
        not isinstance(payload, dict)
        or payload.get("version") != 2
        or payload.get("campaign_id") != campaign_id
        or not isinstance(payload.get("active_hotkeys"), list)
        or not isinstance(payload.get("raw_rewards_by_hotkey"), dict)
    ):
        raise ValueError("recovered validator report payload is invalid")
    active = payload["active_hotkeys"]
    rewards = payload["raw_rewards_by_hotkey"]
    if (
        any(
            not isinstance(hotkey, str)
            or not bt.wallets.is_bittensor_address(hotkey)
            for hotkey in active
        )
        or active
        != sorted(active, key=lambda value: value.encode("ascii"))
        or len(active) != len(set(active))
        or set(active) != set(rewards)
        or any(
            not isinstance(hotkey, str)
            or not bt.wallets.is_bittensor_address(hotkey)
            or type(reward) is not int
            or not 0 <= reward <= 1_000_000
            for hotkey, reward in rewards.items()
        )
    ):
        raise ValueError("recovered validator reward vector is invalid")
    return MappingProxyType(dict(rewards))


class ValidatorNeuron:
    def __init__(
        self,
        *,
        campaign: CampaignManifest,
        netuid: int,
        chain: object,
        wallet: object,
        outcome_source: EpochOutcomeSource,
        initial_state: StabilityState | None,
        state_repository: object,
        settlement_journal: object,
        signer: object,
        retries: int,
        set_weights_armed: bool = False,
    ) -> None:
        self.campaign = CampaignManifest.model_validate(
            campaign.model_dump(mode="python")
        )
        self.netuid = _integer(
            netuid,
            name="netuid",
            minimum=0,
            maximum=2**16 - 1,
        )
        self.retries = _integer(
            retries,
            name="retries",
            minimum=0,
            maximum=20,
        )
        if type(set_weights_armed) is not bool:
            raise TypeError("set_weights_armed must be a boolean")
        self.set_weights_armed = set_weights_armed
        for operation in (
            "fetch_pinned_metagraph",
            "fetch_pinned_metagraph_at",
            "fetch_weight_submission_requirements",
            "submit_exact_weights",
        ):
            if not callable(getattr(chain, operation, None)):
                raise TypeError(f"chain has no {operation} operation")
        if not callable(getattr(outcome_source, "outcomes_for_epoch", None)):
            raise TypeError("outcome source has no outcomes_for_epoch operation")
        for operation in ("preflight_epoch", "publish_epoch"):
            if not callable(getattr(state_repository, operation, None)):
                raise TypeError(f"state repository has no {operation} operation")
        for operation in ("preflight", "prepare", "commit", "recover"):
            if not callable(getattr(settlement_journal, operation, None)):
                raise TypeError(f"settlement journal has no {operation} operation")
        self.chain = chain
        self.wallet = wallet
        self.outcome_source = outcome_source
        self.state_repository = state_repository
        self.settlement_journal = settlement_journal
        self.signer = signer
        configured_epoch = getattr(outcome_source, "configured_epoch", None)
        if configured_epoch is None:
            self._configured_epoch: int | None = None
        else:
            self._configured_epoch = _integer(
                configured_epoch,
                name="configured outcome epoch",
                minimum=0,
                maximum=2**64 - 1,
            )
        try:
            self._signer_hotkey = BittensorHotkeySigner(signer).ss58_address
        except (TypeError, ValueError, RuntimeError) as error:
            raise ValueError(
                "durable settlement requires a validator hotkey signer"
            ) from error
        self.schedule = EpochSchedule(
            epoch_open_block=self.campaign.collection.epoch_open_block,
            epoch_length_blocks=self.campaign.collection.epoch_length_blocks,
        )
        self.policy = IncentivePolicy(
            initial_stability_ppm=self.campaign.stability.initial_value_ppm,
            half_life_days=self.campaign.stability.half_life_days,
            stability_base_multiplier_ppm=(
                self.campaign.weights.stability_base_multiplier_ppm
            ),
            stability_variable_multiplier_ppm=(
                self.campaign.weights.stability_variable_multiplier_ppm
            ),
        )
        self.excluded_hotkeys = _operator_hotkeys(self.campaign)
        self._last_block: int | None = None
        self._last_hash: str | None = None
        self._settlements: dict[int, EpochSettlement] = {}
        self._settlements_by_observed_block: dict[int, EpochSettlement] = {}
        self._pending_publication: _PendingPublication | None = None
        self._outcomes_not_ready_since_block: int | None = None

        if initial_state is None:
            recover = getattr(state_repository, "recover_latest", None)
            if not callable(recover):
                raise TypeError("restart requires repository recovery")
            recovered = recover()
            if recovered.latest.campaign_id != self.campaign.campaign_id:
                raise ValueError("recovered state belongs to another campaign")
            self.state = decode_stability_state(
                bytes.fromhex(recovered.stability_state.payload_hex)
            )
            self._previous_state_root = recovered.state_root
            self._previous_report_sha256 = recovered.report_sha256
            self._last_published_epoch: int | None = recovered.latest.epoch
            self._desired_rewards = _recovered_rewards(
                bytes.fromhex(recovered.report.payload_hex),
                campaign_id=self.campaign.campaign_id,
            )
        else:
            if not isinstance(initial_state, StabilityState):
                raise TypeError("initial_state must be StabilityState or None")
            self.state = initial_state
            self._previous_state_root = GENESIS_STATE_ROOT
            self._previous_report_sha256 = GENESIS_STATE_ROOT
            # A campaign may observe empty miner seeds before its first signed
            # assignment epoch.  Those epochs have no validator state to
            # publish, so genesis starts immediately before the exact epoch
            # authenticated by the configured outcome source.
            self._last_published_epoch = (
                None
                if self._configured_epoch in {None, 0}
                else self._configured_epoch - 1
            )
            self._desired_rewards = MappingProxyType({})
        self._heartbeat_next_block = 0
        self._heartbeat_submitter = BittensorWeightSubmitter(
            chain=self.chain,
            wallet=self.wallet,
            netuid=self.netuid,
            mechanism_id=self.campaign.weights.mechanism_id,
            version_key=self.campaign.weights.version_key,
            retries=self.retries,
            excluded_hotkeys=self.excluded_hotkeys,
        )

    def _check_block(self, block: int, block_hash: str) -> bool:
        _integer(block, name="block", minimum=0, maximum=2**64 - 1)
        if not isinstance(block_hash, str) or _HASH_RE.fullmatch(block_hash) is None:
            raise ValueError("block hash must be canonical lowercase hex")
        if self._last_block is not None:
            if block < self._last_block:
                raise ValueError("block stream regressed")
            if block == self._last_block:
                if block_hash != self._last_hash:
                    raise ValueError("same block arrived with another hash (reorg)")
                return False
        return True

    def _commit_block(self, block: int, block_hash: str) -> None:
        self._last_block = block
        self._last_hash = block_hash

    def _next_unprocessed_settlement_block(self) -> int | None:
        epoch = (
            0
            if self._last_published_epoch is None
            else self._last_published_epoch + 1
        )
        if self._configured_epoch is not None and epoch > self._configured_epoch:
            return None
        return self.schedule.settlement_block(epoch)

    def _maintain_idle_weights(
        self,
        *,
        block: int,
        block_hash: str,
        reserve_for_block: int | None,
    ) -> None:
        if not self.set_weights_armed or block < self._heartbeat_next_block:
            self._commit_block(block, block_hash)
            return
        outcome = run_weight_heartbeat(
            submitter=self._heartbeat_submitter,
            finalized_block=ChainBlockHeader(number=block, hash=block_hash),
            rewards_by_hotkey=self._desired_rewards,
            reserve_for_block=reserve_for_block,
        )
        if outcome.status == "waiting_rate_limit":
            self._heartbeat_next_block = outcome.next_eligible_block
        elif outcome.status == "reserved_for_settlement":
            if reserve_for_block is None:
                raise RuntimeError(
                    "weight heartbeat reserved without a settlement block"
                )
            self._heartbeat_next_block = reserve_for_block
        else:
            self._heartbeat_next_block = (
                block
                + max(
                    WEIGHT_REFRESH_INTERVAL_BLOCKS,
                    outcome.weight_rate_limit_blocks,
                )
            )
        self._commit_block(block, block_hash)

    def _publish_pending(self) -> EpochSettlement:
        pending = self._pending_publication
        if pending is None:
            raise RuntimeError("no pending validator publication")
        try:
            publication = self.state_repository.publish_epoch(
                epoch=pending.epoch,
                report_payload=pending.report_payload,
                stability_payload=pending.stability_payload,
                previous_state_root=pending.previous_state_root,
                signer=self.signer,
            )
        except Exception as error:
            raise SettlementSideEffectUncertain(
                "state publication failed after weight submission; retry may require chain reconciliation after a process crash",
                stage="state_publication",
            ) from error

        settlement = EpochSettlement(
            epoch=pending.epoch,
            observed_block=pending.observed_block,
            discovery_block=pending.discovery_block,
            discovery_block_hash=pending.discovery_block_hash,
            active_hotkeys=pending.active_hotkeys,
            raw_rewards_by_hotkey=pending.raw_rewards_by_hotkey,
            weight_submission=pending.submission,
            state=pending.state,
            previous_state_root=pending.previous_state_root,
            state_root=publication.state_root,
        )
        self.state = pending.state
        self._previous_state_root = publication.state_root
        self._previous_report_sha256 = getattr(
            publication,
            "report_sha256",
            pending.previous_report_sha256,
        )
        self._last_published_epoch = pending.epoch
        self._outcomes_not_ready_since_block = None
        self._desired_rewards = MappingProxyType(
            dict(pending.raw_rewards_by_hotkey)
        )
        self._heartbeat_next_block = (
            pending.processing_block + WEIGHT_REFRESH_INTERVAL_BLOCKS
        )
        self._settlements[pending.epoch] = settlement
        self._settlements_by_observed_block[pending.processing_block] = settlement
        self._commit_block(pending.processing_block, pending.processing_block_hash)
        self._pending_publication = None
        return settlement

    def _validation_descriptors(
        self,
        *,
        epoch: int,
        block: int,
        block_hash: str,
        outcomes: tuple[MinerWindowOutcome, ...],
    ) -> tuple[ValidationOutcomeDescriptor, ...]:
        requires = getattr(
            self.outcome_source,
            "requires_durable_validation_outcomes",
            False,
        )
        if type(requires) is not bool:
            raise TypeError("durable validation-outcome requirement must be boolean")
        reader = getattr(
            self.outcome_source,
            "validation_descriptors_for_epoch",
            None,
        )
        if reader is None:
            if requires:
                raise ValueError(
                    "production outcome source has no durable validation descriptors"
                )
            return ()
        if not callable(reader):
            raise TypeError("validation descriptor reader is not callable")
        try:
            raw_descriptors = reader(campaign=self.campaign, epoch=epoch)
        except TypeError as error:
            raise TypeError("validation descriptor reader has another contract") from error
        if not isinstance(raw_descriptors, tuple):
            raise TypeError("validation descriptors must be a canonical tuple")
        try:
            descriptors = tuple(
                ValidationOutcomeDescriptor.model_validate(
                    value.model_dump(mode="python")
                )
                for value in raw_descriptors
            )
        except (AttributeError, ValueError) as error:
            raise ValueError("validation descriptor is invalid") from error
        expected_hotkeys = tuple(
            sorted(
                (
                    value.miner_hotkey
                    for value in outcomes
                    if value.status is WindowStatus.ACCEPTED
                ),
                key=lambda value: value.encode("ascii"),
            )
        )
        observed_hotkeys = tuple(value.miner_hotkey for value in descriptors)
        if (
            observed_hotkeys != expected_hotkeys
            or len(observed_hotkeys) != len(set(observed_hotkeys))
        ):
            raise ValueError(
                "validation descriptors do not exactly cover accepted miners"
            )
        if self._signer_hotkey is None and descriptors:
            raise ValueError("validation descriptors require a validator signer")
        if any(
            value.validator_hotkey != self._signer_hotkey
            or value.campaign_id != self.campaign.campaign_id
            or value.campaign_hash != self.campaign.campaign_hash
            or value.epoch != epoch
            or value.completed_block != block
            or value.completed_block_hash != block_hash
            for value in descriptors
        ):
            raise ValueError(
                "validation descriptor crosses validator, campaign, epoch, or block"
            )
        return descriptors

    def _resume_committed(
        self,
        *,
        recovered: RecoveredCommittedSettlement,
        processing_block: int,
        processing_block_hash: str,
    ) -> EpochSettlement:
        prepared = recovered.prepared
        if (
            prepared.campaign_hash != self.campaign.campaign_hash
            or prepared.netuid != self.netuid
            or prepared.mechanism_id != self.campaign.weights.mechanism_id
            or prepared.version_key != self.campaign.weights.version_key
            or prepared.previous_state_root != self._previous_state_root
            or prepared.previous_report_sha256 != self._previous_report_sha256
        ):
            raise SettlementJournalError(
                "committed settlement differs from current campaign or state head"
            )
        try:
            state = decode_stability_state(recovered.stability_payload)
        except (TypeError, ValueError) as error:
            raise SettlementJournalError(
                "committed settlement stability payload is invalid"
            ) from error
        receipt = recovered.committed.receipt
        submission = WeightSubmissionResult(
            submitted=prepared.will_submit,
            reason=prepared.submission_reason,
            block=prepared.uid_map_block,
            block_hash=prepared.uid_map_block_hash,
            receipt=receipt,
            dropped_hotkeys=prepared.dropped_hotkeys,
        )
        self._pending_publication = _PendingPublication(
            epoch=prepared.epoch,
            observed_block=prepared.observed_block,
            observed_block_hash=prepared.observed_block_hash,
            discovery_block=prepared.uid_map_block,
            discovery_block_hash=prepared.uid_map_block_hash,
            processing_block=processing_block,
            processing_block_hash=processing_block_hash,
            active_hotkeys=prepared.active_hotkeys,
            raw_rewards_by_hotkey=prepared.raw_rewards_by_hotkey,
            submission=submission,
            state=state,
            previous_state_root=prepared.previous_state_root,
            previous_report_sha256=prepared.previous_report_sha256,
            report_payload=recovered.report_payload,
            stability_payload=recovered.stability_payload,
            receipt_descriptor=receipt,
        )
        return self._publish_pending()

    def on_block(self, block: int, block_hash: str) -> EpochSettlement | None:
        fresh = self._check_block(block, block_hash)
        if not fresh:
            return self._settlements_by_observed_block.get(block)
        if self._pending_publication is not None:
            pending = self._pending_publication
            if (
                block != pending.processing_block
                or block_hash != pending.processing_block_hash
            ):
                raise RuntimeError(
                    "pending settlement must retry its original canonical block"
                )
            return self._publish_pending()
        latest_closed_epoch = self.schedule.latest_closed_epoch(block)
        if latest_closed_epoch is None:
            self._maintain_idle_weights(
                block=block,
                block_hash=block_hash,
                reserve_for_block=self._next_unprocessed_settlement_block(),
            )
            return None
        epoch = (
            0
            if self._last_published_epoch is None
            else self._last_published_epoch + 1
        )
        if self._configured_epoch is not None and epoch > self._configured_epoch:
            # The production composition deliberately loads exactly one signed
            # assignment epoch. Remain quiescent until the operator rolls that
            # input set; never probe a missing next assignment.
            self._maintain_idle_weights(
                block=block,
                block_hash=block_hash,
                reserve_for_block=None,
            )
            return None
        if epoch > latest_closed_epoch:
            self._maintain_idle_weights(
                block=block,
                block_hash=block_hash,
                reserve_for_block=self._next_unprocessed_settlement_block(),
            )
            return None
        recovered = self.settlement_journal.recover(epoch=epoch)
        if recovered is not None:
            if not isinstance(recovered, RecoveredCommittedSettlement):
                raise TypeError("settlement journal returned another recovery type")
            return self._resume_committed(
                recovered=recovered,
                processing_block=block,
                processing_block_hash=block_hash,
            )

        mechanism_id = self.campaign.weights.mechanism_id
        discovery = self.chain.fetch_pinned_metagraph_at(
            netuid=self.netuid,
            mechanism_id=mechanism_id,
            block=block,
        )
        if not isinstance(discovery, PinnedMetagraph):
            raise TypeError("chain returned another metagraph type")
        if discovery.block != block or discovery.block_hash != block_hash:
            raise ValueError(
                "settlement metagraph differs from the processed finalized block"
            )
        if mechanism_id >= discovery.mechanism_count:
            raise ValueError("configured mechanism does not exist at discovery block")
        requirements = self.chain.fetch_weight_submission_requirements(
            netuid=self.netuid,
            mechanism_id=mechanism_id,
            validator_hotkey=self._signer_hotkey,
            block=block,
        )
        if (
            not isinstance(requirements, WeightSubmissionRequirements)
            or requirements.block != block
            or requirements.block_hash != block_hash
            or requirements.validator_hotkey != self._signer_hotkey
        ):
            raise ValueError(
                "weight requirements differ from the finalized settlement block"
            )
        if (
            requirements.last_weight_update_block > 0
            and block - requirements.last_weight_update_block
            < requirements.weight_rate_limit_blocks
        ):
            # Bittensor accepts SetWeights only after the dynamic chain limit.
            # Wait before producing immutable validation evidence so the exact
            # settlement can still bind to the block that performs the write.
            self._commit_block(block, block_hash)
            return None
        registered = registered_miner_hotkeys(
            discovery,
            excluded_hotkeys=self.excluded_hotkeys,
        )
        active_hotkeys = registered
        offered_reader = getattr(
            self.outcome_source,
            "offered_hotkeys_for_epoch",
            None,
        )
        if callable(offered_reader):
            offered_hotkeys = offered_reader(
                campaign=self.campaign,
                epoch=epoch,
            )
            if (
                not isinstance(offered_hotkeys, tuple)
                or len(offered_hotkeys) != len(set(offered_hotkeys))
                or any(
                    not isinstance(value, str)
                    or not bt.wallets.is_bittensor_address(value)
                    or value in self.excluded_hotkeys
                    for value in offered_hotkeys
                )
            ):
                raise ValueError(
                    "offered outcome hotkeys are not unique eligible identities"
                )
        else:
            offered_hotkeys = ()
        eligible_hotkeys = tuple(
            sorted(
                set(active_hotkeys).union(offered_hotkeys),
                key=lambda value: value.encode("ascii"),
            )
        )

        try:
            outcomes = tuple(
                self.outcome_source.outcomes_for_epoch(
                    campaign=self.campaign,
                    epoch=epoch,
                    block=block,
                    block_hash=block_hash,
                    active_hotkeys=eligible_hotkeys,
                )
            )
        except EpochOutcomesNotReady:
            # A future block/opening is a readiness boundary, not an outage
            # outcome. Give the delayed evidence one finalized-block grace
            # period. If it remains unavailable, keep the last valid row fresh
            # while retrying this same oldest closed epoch.
            if self._outcomes_not_ready_since_block is None:
                self._outcomes_not_ready_since_block = block
                self._commit_block(block, block_hash)
            else:
                self._maintain_idle_weights(
                    block=block,
                    block_hash=block_hash,
                    reserve_for_block=None,
                )
            return None
        self._outcomes_not_ready_since_block = None
        outcome_hotkeys = tuple(value.miner_hotkey for value in outcomes)
        if (
            len(outcome_hotkeys) != len(set(outcome_hotkeys))
            or set(outcome_hotkeys) != set(eligible_hotkeys)
        ):
            raise ValueError(
                "validator outcomes do not exactly cover active or offered miners"
            )
        if any(
            value.campaign_id != self.campaign.campaign_id
            or value.epoch != epoch
            for value in outcomes
        ):
            raise ValueError("validator outcome crosses campaign or epoch")
        validation_descriptors = self._validation_descriptors(
            epoch=epoch,
            block=block,
            block_hash=block_hash,
            outcomes=outcomes,
        )

        transition = process_windows(
            state=self.state,
            outcomes=outcomes,
            policy=self.policy,
        )
        working_state = transition.state
        rewards = {
            hotkey: result.raw_reward_ppm
            for hotkey, result in zip(
                outcome_hotkeys,
                transition.transitions,
                strict=True,
            )
        }

        submitter = BittensorWeightSubmitter(
            chain=self.chain,
            wallet=self.wallet,
            netuid=self.netuid,
            mechanism_id=mechanism_id,
            version_key=self.campaign.weights.version_key,
            retries=self.retries,
            excluded_hotkeys=self.excluded_hotkeys,
        )
        reward_plan = submitter.prepare_hotkey_rewards(
            rewards,
            metagraph=discovery,
        )
        settlement_dropped_hotkeys = reward_plan.dropped_hotkeys
        plan = (
            reward_plan
            if reward_plan.will_submit
            else submitter.prepare_self_fallback(metagraph=discovery)
        )
        if plan.will_submit and not self.set_weights_armed:
            raise SetWeightsDisarmed(
                "SetWeights is disarmed; pass --set-weights to authorize "
                "on-chain weight mutation"
            )
        if plan.will_submit:
            plan = submitter.bind_exact_submission(
                plan=plan,
                requirements=requirements,
                validator_hotkey=self._signer_hotkey,
            )
        exact_submission = plan.exact_submission
        exact_weights = (
            () if exact_submission is None else exact_submission.weights_u16
        )
        expected_weight_count = (
            1
            if plan.self_fallback_target is not None
            else len(plan.mapped_rewards)
        )
        if len(exact_weights) != expected_weight_count:
            raise RuntimeError("weight plan is not bound to one exact u16 vector")
        provisional_submission = WeightSubmissionResult(
            submitted=plan.will_submit,
            reason=plan.reason,
            block=plan.block,
            block_hash=plan.block_hash,
            receipt=None,
            dropped_hotkeys=settlement_dropped_hotkeys,
        )
        report_payload = _report_payload(
            campaign=self.campaign,
            epoch=epoch,
            observed_block=block,
            observed_block_hash=block_hash,
            uid_map_block=plan.block,
            uid_map_block_hash=plan.block_hash,
            active_hotkeys=outcome_hotkeys,
            raw_rewards=rewards,
            submission=provisional_submission,
            validation_outcomes=validation_descriptors,
        )
        stability_payload = encode_stability_state(working_state)
        previous_root = self._previous_state_root
        previous_report = self._previous_report_sha256
        self.state_repository.preflight_epoch(
            epoch=epoch,
            report_payload=report_payload,
            stability_payload=stability_payload,
            previous_state_root=previous_root,
            signer=self.signer,
        )
        prepared = self.settlement_journal.prepare(
            campaign_hash=self.campaign.campaign_hash,
            epoch=epoch,
            observed_block=block,
            observed_block_hash=block_hash,
            uid_map_block=plan.block,
            uid_map_block_hash=plan.block_hash,
            netuid=self.netuid,
            mechanism_id=mechanism_id,
            version_key=self.campaign.weights.version_key,
            active_hotkeys=tuple(
                sorted(outcome_hotkeys, key=lambda value: value.encode("ascii"))
            ),
            raw_rewards_by_hotkey=rewards,
            mapped_rewards=tuple(
                MappedHotkeyReward(
                    hotkey=value.hotkey,
                    uid=value.uid,
                    raw_reward_ppm=value.raw_reward_ppm,
                    weight_u16=weight_u16,
                )
                for value, weight_u16 in zip(
                    plan.mapped_rewards,
                    exact_weights,
                    strict=True,
                )
            ),
            self_fallback=(
                None
                if plan.self_fallback_target is None
                else SelfFallbackWeight(
                    hotkey=plan.self_fallback_target.hotkey,
                    uid=plan.self_fallback_target.uid,
                    weight_u16=exact_weights[0],
                )
            ),
            dropped_hotkeys=tuple(
                sorted(
                    settlement_dropped_hotkeys,
                    key=lambda value: value.encode("ascii"),
                )
            ),
            submission_mode=(
                "skipped" if exact_submission is None else exact_submission.mode
            ),
            commit_ciphertext_hex=(
                None
                if exact_submission is None
                or exact_submission.commit_ciphertext is None
                else exact_submission.commit_ciphertext.hex()
            ),
            reveal_round=(
                None if exact_submission is None else exact_submission.reveal_round
            ),
            commit_reveal_version=(
                None
                if exact_submission is None
                else exact_submission.commit_reveal_version
            ),
            previous_state_root=previous_root,
            previous_report_sha256=previous_report,
            report_payload=report_payload,
            stability_payload=stability_payload,
            signer=self.signer,
        )
        if not isinstance(prepared, PreparedSettlement):
            raise TypeError("settlement journal returned another PREPARED type")
        try:
            submission = submitter.execute_plan(plan)
        except WeightSubmissionRejected:
            raise
        except Exception as error:
            raise SettlementReconciliationRequired(
                "SetWeights outcome is uncertain after durable PREPARED; operator reconciliation is required",
                epoch=epoch,
                prepared_key=prepared.key,
                prepared_sha256=prepared.sha256,
            ) from error
        if submission.dropped_hotkeys != settlement_dropped_hotkeys:
            submission = WeightSubmissionResult(
                submitted=submission.submitted,
                reason=submission.reason,
                block=submission.block,
                block_hash=submission.block_hash,
                receipt=submission.receipt,
                dropped_hotkeys=settlement_dropped_hotkeys,
            )
        receipt_descriptor = ChainReceiptDescriptor.from_submission(
            submitted=submission.submitted,
            receipt=submission.receipt,
        )
        try:
            self.settlement_journal.commit(
                prepared=prepared,
                receipt=receipt_descriptor,
                signer=self.signer,
            )
        except Exception as error:
            raise SettlementReconciliationRequired(
                "SetWeights returned but COMMITTED durability is uncertain; operator reconciliation is required",
                epoch=epoch,
                prepared_key=prepared.key,
                prepared_sha256=prepared.sha256,
            ) from error
        self._pending_publication = _PendingPublication(
            epoch=epoch,
            observed_block=block,
            observed_block_hash=block_hash,
            # EpochSettlement's historical field name is retained, but its
            # semantic is the final fresh UID-map block that actually binds the
            # SetWeights intent, not the earlier eligibility discovery view.
            discovery_block=plan.block,
            discovery_block_hash=plan.block_hash,
            processing_block=block,
            processing_block_hash=block_hash,
            active_hotkeys=outcome_hotkeys,
            raw_rewards_by_hotkey=rewards,
            submission=submission,
            state=working_state,
            previous_state_root=previous_root,
            previous_report_sha256=previous_report,
            report_payload=report_payload,
            stability_payload=stability_payload,
            receipt_descriptor=receipt_descriptor,
        )
        return self._publish_pending()

    def ready_for_epoch_rollover(self, next_epoch: int) -> bool:
        """Return whether the immediately preceding epoch is durably published."""

        checked = _integer(
            next_epoch,
            name="next_epoch",
            minimum=1,
            maximum=2**64 - 1,
        )
        if (
            self._configured_epoch is not None
            and checked != self._configured_epoch + 1
        ):
            return False
        return (
            self._pending_publication is None
            and self._last_published_epoch is not None
            and self._last_published_epoch >= checked - 1
        )

    def run(self, blocks) -> None:
        for header in blocks:
            self.on_block(
                int(header.number),
                str(header.hash).removeprefix("0x").lower(),
            )

    def close(self) -> None:
        close_outcomes = getattr(self.outcome_source, "close", None)
        if callable(close_outcomes):
            close_outcomes()


@dataclass(frozen=True, slots=True)
class ValidatorNeuronConfig:
    network: str
    netuid: int
    validator_hotkey: str
    campaign: CampaignManifest
    mechanism_id: int
    version_key: int
    set_weights_armed: bool

    @classmethod
    def from_options(cls, options: Mapping[str, str]) -> "ValidatorNeuronConfig":
        campaign = _load_campaign(options)
        return cls(
            network=_required(options, "network"),
            netuid=_option_integer(
                options,
                "netuid",
                minimum=0,
                maximum=2**16 - 1,
            ),
            validator_hotkey=_required(
                options,
                "validator_hotkey_ss58",
            ),
            campaign=campaign,
            mechanism_id=campaign.weights.mechanism_id,
            version_key=campaign.weights.version_key,
            set_weights_armed=_set_weights_arm(options),
        )


def build_live_neuron(
    options: Mapping[str, str],
    *,
    bootstrap_builder: Callable[..., object] | None = None,
) -> tuple[ValidatorNeuron, LiveBittensorChain]:
    """Build network and storage dependencies only under explicit CLI startup."""

    values = dict(options)
    chain = LiveBittensorChain.from_network(_required(values, "network"))
    bootstrap: ValidatorBootstrap | None = None
    try:
        wallet = _load_wallet(
            values,
            expected_hotkey=None,
            wallet_factory=bt.Wallet,
        )
        values["validator_hotkey_ss58"] = wallet.hotkey.ss58_address
        if "epoch_bundle_root" in values:
            from services.epoch_bundle import (  # noqa: PLC0415
                prepare_initial_epoch_options,
            )

            values = prepare_initial_epoch_options(
                role="validator",
                options=values,
                block_source=chain,
                validator_signer=wallet.hotkey,
            )
        config = ValidatorNeuronConfig.from_options(values)
        if bootstrap_builder is None:
            from services.validator_production import (  # noqa: PLC0415
                build_validator_bootstrap,
            )

            bootstrap_builder = build_validator_bootstrap
        raw_bootstrap = bootstrap_builder(
            options=values,
            campaign=config.campaign,
            validator_signer=wallet.hotkey,
        )
        if type(raw_bootstrap) is not ValidatorBootstrap:
            raise TypeError("validator builder must return an exact ValidatorBootstrap")
        bootstrap = ValidatorBootstrap(
            outcome_source=raw_bootstrap.outcome_source,
            state_repository=raw_bootstrap.state_repository,
            settlement_journal=raw_bootstrap.settlement_journal,
        )
        if bootstrap.settlement_journal is None:
            raise TypeError("production validator requires a durable settlement journal")
        initial_state = (
            StabilityState.empty()
            if values.get("validator_allow_genesis") == "1"
            else None
        )
        neuron = ValidatorNeuron(
            campaign=config.campaign,
            netuid=config.netuid,
            chain=chain,
            wallet=wallet,
            outcome_source=bootstrap.outcome_source,
            initial_state=initial_state,
            state_repository=bootstrap.state_repository,
            settlement_journal=bootstrap.settlement_journal,
            signer=wallet.hotkey,
            set_weights_armed=config.set_weights_armed,
            retries=_option_integer(
                values,
                "chain_retries",
                minimum=0,
                maximum=20,
                default="2",
            ),
        )
        return neuron, chain
    except Exception:
        if bootstrap is not None:
            close_outcomes = getattr(bootstrap.outcome_source, "close", None)
            if callable(close_outcomes):
                close_outcomes()
        chain.close()
        raise


def run_live_validator(
    neuron: ValidatorNeuron,
    blocks,
    *,
    epoch_reloader: FinalizedEpochReloader | None = None,
) -> None:
    if epoch_reloader is None:
        neuron.run(blocks)
        return
    for header in blocks:
        block = int(header.number)
        block_hash = str(header.hash).removeprefix("0x").lower()
        if _HASH_RE.fullmatch(block_hash) is None:
            raise ValueError("validator block header hash is invalid")
        epoch_reloader.observe_finalized(block, block_hash)
        selected = epoch_reloader.runtime_for_finalized_block(block)
        if selected is None:
            continue
        on_block = getattr(selected, "on_block", None)
        if not callable(on_block):
            raise TypeError("reloaded validator has no on_block operation")
        on_block(block, block_hash)


def main(*, options: Mapping[str, str]) -> int:
    neuron, chain = build_live_neuron(options)
    epoch_reloader: FinalizedEpochReloader | None = None
    try:
        epoch_reloader = load_configured_epoch_reloader(
            role="validator",
            options=options,
            initial_runtime=neuron,
            block_source=chain,
        )
        run_live_validator(
            neuron,
            chain.blocks(),
            epoch_reloader=epoch_reloader,
        )
    finally:
        try:
            if epoch_reloader is not None:
                epoch_reloader.close()
            else:
                close_neuron = getattr(neuron, "close", None)
                if callable(close_neuron):
                    close_neuron()
                else:
                    close_outcomes = getattr(neuron.outcome_source, "close", None)
                    if callable(close_outcomes):
                        close_outcomes()
        finally:
            chain.close()
    return 0


